import { useState, useRef, useEffect } from "react";
import { useSQLQuery } from "@motherduck/react-sql-query";
import * as d3 from "d3";
import {
  BarChart, Bar, XAxis, YAxis, Tooltip, ResponsiveContainer,
  ScatterChart, Scatter, Cell,
} from "recharts";

const N = (v: unknown): number => (v != null ? Number(v) : 0);

/* ── Design tokens ─────────────────────────────────────────────── */

const T = {
  fg: "#1a1a1a",
  muted: "#777",
  rule: "#d4d4d4",
  bg: "#f8f8f8",
  sand: "#f0ebe0",
  link: "#6FC2FF",
  accent: "#6FC2FF",
  mono: "'SF Mono', 'Cascadia Code', 'Fira Code', Menlo, monospace",
  sans: "system-ui, -apple-system, 'Helvetica Neue', Helvetica, sans-serif",
} as const;

/* ── Tab config ────────────────────────────────────────────────── */

const TABS = [
  { id: "pioneers", names: "Nightingale, Du Bois, Sankey", period: "1858–1900", tagline: "Data as argument", slideCount: 3 },
  { id: "grammarians", names: "Isotype & Swiss Design", period: "1920s–1960s", tagline: "The science of seeing", slideCount: 5 },
  { id: "minimalists", names: "Tufte & Rosling", period: "1983–2006", tagline: "Less ink, more story", slideCount: 4 },
  { id: "interactive", names: "Bostock & the NYT", period: "2010s–now", tagline: "The chart as interface", slideCount: 4 },
] as const;

type TabId = (typeof TABS)[number]["id"];

/* first slide index for each tab */
const TAB_START: Record<TabId, number> = { pioneers: 0, grammarians: 3, minimalists: 8, interactive: 12 };
const TOTAL_SLIDES = 16;

function tabForSlide(idx: number): TabId {
  if (idx >= 12) return "interactive";
  if (idx >= 8) return "minimalists";
  if (idx >= 3) return "grammarians";
  return "pioneers";
}

const REGION_LABELS: Record<string, string> = {
  "1_Afr": "Africa", "2_Amr": "Americas", "3_Sear": "SE Asia",
  "4_Eur": "Europe", "5_Emr": "E. Mediterranean", "6_Wpr": "W. Pacific",
};

/* ══════════════════════════════════════════════════════════════════
   Root component
   ══════════════════════════════════════════════════════════════════ */

export default function DataVizHistory() {
  const [slideIdx, setSlideIdx] = useState(0);
  const [hoveredTab, setHoveredTab] = useState<TabId | null>(null);

  const activeTab = tabForSlide(slideIdx);
  const localIdx = slideIdx - TAB_START[activeTab];

  const regionQuery = useSQLQuery(`
    SELECT who_region as region, ROUND(AVG(pm25_concentration), 1) as avg_pm25,
      COUNT(DISTINCT country_name) as countries, COUNT(DISTINCT city) as cities
    FROM "sample_data"."who"."ambient_air_quality"
    WHERE pm25_concentration IS NOT NULL AND who_region NOT IN ('7_NonMS')
    GROUP BY who_region ORDER BY avg_pm25 DESC
  `);

  const rows = (Array.isArray(regionQuery.data) ? regionQuery.data : []).map(r => ({
    region: REGION_LABELS[r.region as string] || (r.region as string),
    avg_pm25: N(r.avg_pm25), countries: N(r.countries), cities: N(r.cities),
  }));

  const prev = () => setSlideIdx(i => Math.max(0, i - 1));
  const next = () => setSlideIdx(i => Math.min(TOTAL_SLIDES - 1, i + 1));

  return (
    <div style={{ background: T.bg, minHeight: "100%", maxWidth: 1100, margin: "0 auto", fontFamily: T.sans, zoom: 1.2 }}>
      {/* Tab bar */}
      <div style={{ display: "flex", paddingLeft: 32, paddingRight: 32, borderBottom: `1px solid ${T.rule}` }}>
        {TABS.map(s => {
          const isActive = activeTab === s.id;
          return (
            <button
              key={s.id}
              onClick={() => setSlideIdx(TAB_START[s.id])}
              onMouseEnter={() => setHoveredTab(s.id)}
              onMouseLeave={() => setHoveredTab(null)}
              style={{
                flex: 1,
                textAlign: "left",
                paddingLeft: 8,
                paddingRight: 8,
                paddingTop: 16,
                paddingBottom: 16,
                borderBottom: isActive ? `2px solid ${T.fg}` : "2px solid transparent",
                opacity: isActive ? 1 : hoveredTab === s.id ? 0.7 : 0.4,
                cursor: "pointer",
                transition: "opacity 0.15s ease",
              }}
            >
              <p style={{ fontSize: 10, fontWeight: 700, letterSpacing: "0.08em", textTransform: "uppercase", color: T.fg, marginBottom: 2 }}>
                {s.period}
              </p>
              <p style={{ fontSize: 13, fontWeight: 600, color: T.fg }}>{s.names}</p>
              <p style={{ fontSize: 11, color: T.muted }}>{s.tagline}</p>
            </button>
          );
        })}
      </div>

      {/* Slide content with clickable side gutters */}
      <div style={{ display: "flex", position: "relative" }}>
        {/* Left gutter — click to go back */}
        <div
          onClick={slideIdx > 0 ? prev : undefined}
          style={{
            width: 32, flexShrink: 0, cursor: slideIdx > 0 ? "pointer" : "default",
            display: "flex", alignItems: "center", justifyContent: "center",
            opacity: 0, transition: "opacity 0.2s ease",
          }}
          onMouseEnter={e => { if (slideIdx > 0) (e.currentTarget as HTMLDivElement).style.opacity = "1"; }}
          onMouseLeave={e => { (e.currentTarget as HTMLDivElement).style.opacity = "0"; }}
        >
          {slideIdx > 0 && (
            <svg width="20" height="20" viewBox="0 0 24 24" fill="none" stroke={T.muted} strokeWidth="2" strokeLinecap="round" strokeLinejoin="round">
              <polyline points="15 18 9 12 15 6" />
            </svg>
          )}
        </div>

        <div style={{ flex: 1, minWidth: 0, paddingTop: 24, paddingBottom: 24, minHeight: 620, maxHeight: 620, overflowY: "auto" }}>
          {activeTab === "pioneers" && <PioneerSlide index={localIdx} />}
          {activeTab === "grammarians" && <GrammarianSlide index={localIdx} data={rows} loading={regionQuery.isLoading} />}
          {activeTab === "minimalists" && <MinimalistSlide index={localIdx} data={rows} loading={regionQuery.isLoading} />}
          {activeTab === "interactive" && <InteractiveSlide index={localIdx} data={rows} loading={regionQuery.isLoading} />}
        </div>

        {/* Right gutter — click to go forward */}
        <div
          onClick={slideIdx < TOTAL_SLIDES - 1 ? next : undefined}
          style={{
            width: 32, flexShrink: 0, cursor: slideIdx < TOTAL_SLIDES - 1 ? "pointer" : "default",
            display: "flex", alignItems: "center", justifyContent: "center",
            opacity: 0, transition: "opacity 0.2s ease",
          }}
          onMouseEnter={e => { if (slideIdx < TOTAL_SLIDES - 1) (e.currentTarget as HTMLDivElement).style.opacity = "1"; }}
          onMouseLeave={e => { (e.currentTarget as HTMLDivElement).style.opacity = "0"; }}
        >
          {slideIdx < TOTAL_SLIDES - 1 && (
            <svg width="20" height="20" viewBox="0 0 24 24" fill="none" stroke={T.muted} strokeWidth="2" strokeLinecap="round" strokeLinejoin="round">
              <polyline points="9 18 15 12 9 6" />
            </svg>
          )}
        </div>
      </div>

      {/* Slide navigation */}
      <SlideNav slideIdx={slideIdx} total={TOTAL_SLIDES} onPrev={prev} onNext={next} />
    </div>
  );
}

/* ══════════════════════════════════════════════════════════════════
   Shared layout components
   ══════════════════════════════════════════════════════════════════ */

function SplitRow({ text, chart }: { text: React.ReactNode; chart: React.ReactNode }) {
  return (
    <div style={{ display: "flex", flexDirection: "row", gap: 24, marginBottom: 72, paddingTop: 8 }}>
      <div style={{ width: "40%", flexShrink: 0 }}>{text}</div>
      <div style={{ width: "60%", minWidth: 0 }}>{chart}</div>
    </div>
  );
}

function SectionTitle({ name, subtitle }: { name: string; subtitle: string }) {
  return (
    <div style={{ marginBottom: 12 }}>
      <h2 style={{ fontSize: 20, fontWeight: 700, color: T.fg, lineHeight: 1.2, marginBottom: 4 }}>{name}</h2>
      <p style={{ fontSize: 11, color: T.muted, letterSpacing: "0.02em" }}>{subtitle}</p>
    </div>
  );
}

function WikiLink({ href, label }: { href: string; label: string }) {
  const [hovered, setHovered] = useState(false);
  return (
    <a href={href} target="_blank" rel="noopener noreferrer"
      onMouseEnter={() => setHovered(true)}
      onMouseLeave={() => setHovered(false)}
      style={{
        fontSize: 11, color: hovered ? T.fg : T.link, display: "inline-block", marginTop: 8,
        transition: "color 0.15s ease",
      }}
    >{label} &#8599;</a>
  );
}

function DivePrompt({ prompt }: { prompt: string }) {
  const [copied, setCopied] = useState(false);

  const handleCopy = () => {
    navigator.clipboard.writeText(prompt).then(() => {
      setCopied(true);
      setTimeout(() => setCopied(false), 1500);
    });
  };

  return (
    <div style={{ marginTop: 16, padding: "10px 12px", background: "#eee", borderLeft: `2px solid ${T.fg}`, position: "relative" }}>
      <div style={{ display: "flex", justifyContent: "space-between", alignItems: "center", marginBottom: 4 }}>
        <p style={{ fontSize: 10, fontWeight: 600, color: T.muted, letterSpacing: "0.06em", textTransform: "uppercase", margin: 0 }}>
          Try this in a Dive
        </p>
        <button
          onClick={handleCopy}
          style={{
            background: "none", border: "none", cursor: "pointer", padding: 2,
            color: copied ? "#2d7a00" : T.muted, display: "flex", alignItems: "center", gap: 4,
          }}
          title="Copy prompt"
        >
          {copied ? (
            <svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round">
              <polyline points="20 6 9 17 4 12" />
            </svg>
          ) : (
            <svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round">
              <rect x="9" y="9" width="13" height="13" rx="2" ry="2" />
              <path d="M5 15H4a2 2 0 0 1-2-2V4a2 2 0 0 1 2-2h9a2 2 0 0 1 2 2v1" />
            </svg>
          )}
          <span style={{ fontSize: 10 }}>{copied ? "Copied" : "Copy"}</span>
        </button>
      </div>
      <p style={{ fontSize: 12, color: T.fg, lineHeight: 1.6, fontFamily: T.mono, margin: 0 }}>
        {prompt}
      </p>
    </div>
  );
}

function KeyLesson({ text }: { text: string }) {
  return (
    <div style={{ marginTop: 24, display: "flex", gap: 10, alignItems: "flex-start" }}>
      <svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke={T.fg} strokeWidth="2.5" strokeLinecap="round" strokeLinejoin="round" style={{ flexShrink: 0, marginTop: 2 }}>
        <path d="M22 10v6M2 10l10-5 10 5-10 5z" />
        <path d="M6 12v5c0 1.1 2.7 3 6 3s6-1.9 6-3v-5" />
      </svg>
      <p style={{ fontSize: 13, fontWeight: 700, color: T.fg, lineHeight: 1.5, margin: 0 }}>
        {text}
      </p>
    </div>
  );
}

function SlideNav({ slideIdx, total, onPrev, onNext }: { slideIdx: number; total: number; onPrev: () => void; onNext: () => void }) {
  const [hoveredBtn, setHoveredBtn] = useState<"prev" | "next" | null>(null);
  const isFirst = slideIdx === 0;
  const isLast = slideIdx === total - 1;
  const currentTab = tabForSlide(slideIdx);
  const tab = TABS.find(t => t.id === currentTab)!;
  const localIdx = slideIdx - TAB_START[currentTab];

  const btnBase = {
    border: `1.5px solid ${T.fg}`, cursor: "pointer", display: "flex" as const, alignItems: "center" as const, gap: 10,
    fontSize: 15, fontWeight: 700 as const, fontFamily: T.sans, transition: "all 0.15s ease",
    padding: "10px 20px", borderRadius: 6,
  };

  return (
    <div style={{ borderTop: `1px solid ${T.rule}`, marginLeft: 32, marginRight: 32, padding: "16px 0 24px", display: "flex", justifyContent: "space-between", alignItems: "center" }}>
      <button
        onClick={onPrev}
        disabled={isFirst}
        onMouseEnter={() => setHoveredBtn("prev")}
        onMouseLeave={() => setHoveredBtn(null)}
        style={{
          ...btnBase,
          background: isFirst ? "none" : hoveredBtn === "prev" ? "#e8e8e8" : "none",
          color: isFirst ? T.rule : hoveredBtn === "prev" ? T.fg : T.fg,
          borderColor: isFirst ? T.rule : T.fg,
          cursor: isFirst ? "default" : "pointer",
        }}
      >
        <svg width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2.5" strokeLinecap="round" strokeLinejoin="round">
          <polyline points="15 18 9 12 15 6" />
        </svg>
        Prev
      </button>

      {/* Dot indicators */}
      <div style={{ display: "flex", alignItems: "center", gap: 6 }}>
        <span style={{ fontSize: 10, color: T.muted, marginRight: 4 }}>{tab.period}</span>
        {Array.from({ length: tab.slideCount }).map((_, i) => (
          <div key={i} style={{
            width: i === localIdx ? 18 : 6, height: 6, borderRadius: 3,
            background: i === localIdx ? T.fg : T.rule,
            transition: "all 0.2s ease",
          }} />
        ))}
        <span style={{ fontSize: 10, color: T.muted, marginLeft: 4 }}>{slideIdx + 1}/{total}</span>
      </div>

      <button
        onClick={onNext}
        disabled={isLast}
        onMouseEnter={() => setHoveredBtn("next")}
        onMouseLeave={() => setHoveredBtn(null)}
        style={{
          ...btnBase,
          background: isLast ? "none" : hoveredBtn === "next" ? T.fg : "none",
          color: isLast ? T.rule : hoveredBtn === "next" ? "#fff" : T.fg,
          borderColor: isLast ? T.rule : T.fg,
          cursor: isLast ? "default" : "pointer",
        }}
      >
        Next
        <svg width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2.5" strokeLinecap="round" strokeLinejoin="round">
          <polyline points="9 18 15 12 9 6" />
        </svg>
      </button>
    </div>
  );
}

function ChartFootnote({ text }: { text: string }) {
  return (
    <p style={{ fontSize: 9, color: T.muted, marginTop: 6, fontStyle: "italic" }}>{text}</p>
  );
}

function LegendRow({ items }: { items: { color: string; label: string }[] }) {
  return (
    <div style={{ display: "flex", gap: 16, marginTop: 10 }}>
      {items.map(item => (
        <div key={item.label} style={{ display: "flex", alignItems: "center", gap: 4 }}>
          <div style={{ width: 10, height: 10, background: item.color, borderRadius: 1 }} />
          <span style={{ fontSize: 10, color: T.muted }}>{item.label}</span>
        </div>
      ))}
    </div>
  );
}

/* ══════════════════════════════════════════════════════════════════
   §1 — PIONEERS
   ══════════════════════════════════════════════════════════════════ */

const NIGHTINGALE_DATA = [
  { month: "Apr", disease: 110, wounds: 32, other: 18 },
  { month: "May", disease: 135, wounds: 28, other: 15 },
  { month: "Jun", disease: 168, wounds: 42, other: 20 },
  { month: "Jul", disease: 245, wounds: 65, other: 25 },
  { month: "Aug", disease: 310, wounds: 52, other: 30 },
  { month: "Sep", disease: 280, wounds: 38, other: 22 },
  { month: "Oct", disease: 220, wounds: 30, other: 19 },
  { month: "Nov", disease: 190, wounds: 25, other: 16 },
  { month: "Dec", disease: 160, wounds: 20, other: 14 },
  { month: "Jan", disease: 340, wounds: 45, other: 35 },
  { month: "Feb", disease: 290, wounds: 35, other: 28 },
  { month: "Mar", disease: 200, wounds: 22, other: 17 },
];

const DUBOIS_DATA = [
  { range: "$100–200", rent: 47, food: 28, clothing: 10, tax: 5, other: 10 },
  { range: "$200–300", rent: 40, food: 30, clothing: 12, tax: 5, other: 13 },
  { range: "$300–400", rent: 35, food: 28, clothing: 14, tax: 6, other: 17 },
  { range: "$400–500", rent: 30, food: 25, clothing: 15, tax: 7, other: 23 },
  { range: "$500–750", rent: 25, food: 22, clothing: 16, tax: 8, other: 29 },
  { range: "$750–1000", rent: 20, food: 18, clothing: 17, tax: 9, other: 36 },
  { range: "Over $1000", rent: 15, food: 14, clothing: 16, tax: 10, other: 45 },
];

const SANKEY_NODES = [
  { id: "Coal Energy", x: 0 }, { id: "Boiler", x: 1 }, { id: "Steam", x: 2 },
  { id: "Engine", x: 3 }, { id: "Useful Work", x: 4 },
  { id: "Flue Gases", x: 1 }, { id: "Radiation Loss", x: 2 },
  { id: "Condensation", x: 3 }, { id: "Friction", x: 4 },
];

const SANKEY_LINKS = [
  { source: "Coal Energy", target: "Boiler", value: 100 },
  { source: "Boiler", target: "Flue Gases", value: 22 },
  { source: "Boiler", target: "Steam", value: 78 },
  { source: "Steam", target: "Radiation Loss", value: 8 },
  { source: "Steam", target: "Engine", value: 70 },
  { source: "Engine", target: "Condensation", value: 36 },
  { source: "Engine", target: "Friction", value: 4 },
  { source: "Engine", target: "Useful Work", value: 30 },
];

// ── Nightingale Rose (D3) ──────────────────────────────────────────

function NightingaleRose() {
  const svgRef = useRef<SVGSVGElement>(null);

  useEffect(() => {
    if (!svgRef.current) return;
    const svg = d3.select(svgRef.current);
    svg.selectAll("*").remove();

    const size = 340;
    const radius = size / 2 - 30;
    const g = svg.attr("viewBox", `0 0 ${size} ${size}`)
      .append("g").attr("transform", `translate(${size / 2},${size / 2})`);

    const slice = (2 * Math.PI) / 12;
    const maxVal = d3.max(NIGHTINGALE_DATA, d => d.disease + d.wounds + d.other) || 400;
    const rScale = d3.scaleSqrt().domain([0, maxVal]).range([0, radius]);

    const layers: { key: "disease" | "wounds" | "other"; color: string }[] = [
      { key: "disease", color: "#8b9fae" },
      { key: "wounds", color: "#c45b6a" },
      { key: "other", color: "#3a3a3a" },
    ];

    NIGHTINGALE_DATA.forEach((d, i) => {
      const startAngle = i * slice - Math.PI / 2;
      let cum = d.disease + d.wounds + d.other;

      layers.forEach(layer => {
        const outerR = rScale(cum);
        cum -= d[layer.key];
        const innerR = rScale(Math.max(0, cum));

        g.append("path")
          .attr("d", d3.arc<unknown>()
            .innerRadius(innerR).outerRadius(outerR)
            .startAngle(startAngle + Math.PI / 2)
            .endAngle(startAngle + slice + Math.PI / 2)({}) as string)
          .attr("fill", layer.color)
          .attr("stroke", T.sand).attr("stroke-width", 0.5)
          .attr("opacity", 0.85);
      });

      const labelR = radius + 16;
      const mid = startAngle + slice / 2;
      g.append("text")
        .attr("x", labelR * Math.cos(mid)).attr("y", labelR * Math.sin(mid))
        .attr("text-anchor", "middle").attr("dominant-baseline", "middle")
        .attr("font-size", 10).attr("fill", T.muted)
        .attr("font-family", T.sans).text(d.month);
    });
  }, []);

  return <svg ref={svgRef} style={{ width: "100%", maxWidth: 340, height: "auto", aspectRatio: "1", display: "block", margin: "0 auto" }} />;
}

// ── Du Bois stacked bars ───────────────────────────────────────────

function DuBoisBars() {
  const cats = [
    { key: "rent", color: "#2d2d2d", label: "Rent" },
    { key: "food", color: "#c4564e", label: "Food" },
    { key: "clothing", color: "#d4a84b", label: "Clothing" },
    { key: "tax", color: "#7a6e5d", label: "Tax" },
    { key: "other", color: "#a8917a", label: "Other" },
  ] as const;

  return (
    <div>
      <div style={{ display: "flex", gap: 16, marginBottom: 12 }}>
        {cats.map(c => (
          <div key={c.key} style={{ display: "flex", alignItems: "center", gap: 4 }}>
            <div style={{ width: 10, height: 10, background: c.color }} />
            <span style={{ fontSize: 9, color: "#2d2d2d", fontFamily: "Georgia, serif" }}>{c.label}</span>
          </div>
        ))}
      </div>
      <div style={{ display: "flex", flexDirection: "column", gap: 4 }}>
        {DUBOIS_DATA.map(d => (
          <div key={d.range} style={{ display: "flex", alignItems: "center", gap: 8 }}>
            <span style={{ width: 75, fontSize: 10, textAlign: "right", color: "#2d2d2d", fontFamily: "Georgia, serif", flexShrink: 0 }}>
              {d.range}
            </span>
            <div style={{ display: "flex", flex: 1, height: 22 }}>
              {cats.map(c => (
                <div key={c.key} style={{ width: `${(d as Record<string, number>)[c.key]}%`, background: c.color, height: "100%" }} />
              ))}
            </div>
          </div>
        ))}
      </div>
    </div>
  );
}

// ── Sankey (D3) ────────────────────────────────────────────────────

function SankeyDiagram() {
  const svgRef = useRef<SVGSVGElement>(null);

  useEffect(() => {
    if (!svgRef.current) return;
    const svg = d3.select(svgRef.current);
    svg.selectAll("*").remove();

    const width = 640, height = 260;
    const margin = { top: 10, right: 100, bottom: 10, left: 110 };
    const innerW = width - margin.left - margin.right;
    const innerH = height - margin.top - margin.bottom;

    svg.attr("viewBox", `0 0 ${width} ${height}`);
    const g = svg.append("g").attr("transform", `translate(${margin.left},${margin.top})`);

    const columns: Record<number, string[]> = { 0: [], 1: [], 2: [], 3: [], 4: [] };
    SANKEY_NODES.forEach(n => columns[n.x].push(n.id));

    const xScale = d3.scalePoint<number>().domain([0, 1, 2, 3, 4]).range([0, innerW]);

    const nodeValues: Record<string, number> = {};
    const nodeInc: Record<string, number> = {};
    const nodeOut: Record<string, number> = {};
    SANKEY_NODES.forEach(n => {
      const inc = SANKEY_LINKS.filter(l => l.target === n.id).reduce((s, l) => s + l.value, 0);
      const out = SANKEY_LINKS.filter(l => l.source === n.id).reduce((s, l) => s + l.value, 0);
      nodeValues[n.id] = Math.max(inc, out);
      nodeInc[n.id] = inc;
      nodeOut[n.id] = out;
    });

    const thick = 8;
    const vScale = innerH / 120;

    const pos: Record<string, { x: number; y: number; h: number }> = {};
    Object.entries(columns).forEach(([col, ids]) => {
      const totalH = ids.reduce((s, id) => s + nodeValues[id] * vScale, 0);
      const gap = ids.length > 1 ? (innerH - totalH) / (ids.length - 1) : 0;
      let cy = (innerH - totalH - gap * (ids.length - 1)) / 2;
      ids.forEach(id => {
        const h = nodeValues[id] * vScale;
        pos[id] = { x: xScale(Number(col)) || 0, y: cy, h };
        cy += h + gap;
      });
    });

    const srcOff: Record<string, number> = {};
    const tgtOff: Record<string, number> = {};
    const lossNodes = new Set(["Flue Gases", "Radiation Loss", "Condensation", "Friction"]);

    SANKEY_LINKS.forEach(link => {
      const src = pos[link.source], tgt = pos[link.target];
      const linkH = link.value * vScale;
      const y0 = src.y + (srcOff[link.source] || 0);
      const y1 = tgt.y + (tgtOff[link.target] || 0);
      srcOff[link.source] = (srcOff[link.source] || 0) + linkH;
      tgtOff[link.target] = (tgtOff[link.target] || 0) + linkH;

      const x0 = src.x + thick, x1 = tgt.x, midX = (x0 + x1) / 2;
      const isLoss = lossNodes.has(link.target);

      g.append("path")
        .attr("d", `M ${x0} ${y0} C ${midX} ${y0}, ${midX} ${y1}, ${x1} ${y1} L ${x1} ${y1 + linkH} C ${midX} ${y1 + linkH}, ${midX} ${y0 + linkH}, ${x0} ${y0 + linkH} Z`)
        .attr("fill", isLoss ? "#c45b6a" : "#8b9fae")
        .attr("opacity", isLoss ? 0.5 : 0.6);
    });

    SANKEY_NODES.forEach(n => {
      const p = pos[n.id];
      const isLoss = lossNodes.has(n.id);
      const isUseful = n.id === "Useful Work";

      g.append("rect").attr("x", p.x).attr("y", p.y).attr("width", thick).attr("height", p.h)
        .attr("fill", isUseful ? "#2d7a00" : isLoss ? "#c45b6a" : "#3a3a3a");

      // Show outgoing value for sources, incoming for sinks
      const displayVal = nodeOut[n.id] > 0 ? nodeOut[n.id] : nodeInc[n.id];
      g.append("text")
        .attr("x", n.x === 0 ? p.x - 4 : p.x + thick + 4)
        .attr("y", p.y + p.h / 2)
        .attr("text-anchor", n.x === 0 ? "end" : "start")
        .attr("dominant-baseline", "middle")
        .attr("font-size", 10).attr("fill", T.fg).attr("font-family", T.sans)
        .text(`${n.id} (${displayVal})`);
    });
  }, []);

  return <svg ref={svgRef} style={{ width: "100%", height: "auto", aspectRatio: "640/260" }} />;
}

// ── ChartFrame: sand-colored card with legend + footnote ──────────

function ChartFrame({ children, legend, footnote, bg }: {
  children: React.ReactNode;
  legend?: { color: string; label: string }[];
  footnote: string;
  bg?: string;
}) {
  return (
    <div style={{ background: bg ?? T.sand, padding: "20px 20px 14px" }}>
      {children}
      {legend && <LegendRow items={legend} />}
      <ChartFootnote text={footnote} />
    </div>
  );
}

