                    </span>
                    <div style={{ display: "flex", flexWrap: "wrap", gap: 4 }}>
                      {Array.from({ length: Math.min(r.countries, 50) }).map((_, i) => (
                        <div key={i} style={{
                          width: 9, height: 9, borderRadius: "50%",
                          background: i < Math.round(r.avg_pm25 / 10) ? "#FFDE02" : "#fff",
