function WhitespaceDemo() {
  const svgRef = useRef<SVGSVGElement>(null);

  useEffect(() => {
    if (!svgRef.current) return;
    const svg = d3.select(svgRef.current);
    svg.selectAll("*").remove();

    const w = 520, h = 260;
    svg.attr("viewBox", `0 0 ${w} ${h}`);

    const data = [
      { label: "SE Asia", value: 53 },
      { label: "W. Pacific", value: 40 },
      { label: "E. Med.", value: 38 },
      { label: "Africa", value: 28 },
      { label: "Europe", value: 14 },
      { label: "Americas", value: 10 },
    ];

    const barH = 18, gap = 8;
    const maxVal = 60;

    // Left side: noisy
    const lx = 20, lBarStart = 90;
    svg.append("text").attr("x", w / 4).attr("y", 20)
      .attr("text-anchor", "middle").attr("font-size", 11).attr("font-weight", 700)
      .attr("fill", T.fg).attr("font-family", T.sans).text("With noise");

    // Background box
    svg.append("rect").attr("x", lx - 4).attr("y", 30).attr("width", w / 2 - 30).attr("height", data.length * (barH + gap) + 16)
      .attr("fill", "none").attr("stroke", "#bbb").attr("stroke-width", 1);

    // Grid lines
    for (let v = 0; v <= 60; v += 20) {
      const x = lBarStart + (v / maxVal) * 140;
      svg.append("line").attr("x1", x).attr("y1", 34).attr("x2", x).attr("y2", 30 + data.length * (barH + gap) + 12)
        .attr("stroke", "#ccc").attr("stroke-width", 0.5);
