      svg.append("rect").attr("x", lBarStart).attr("y", y).attr("width", barW).attr("height", barH)
        .attr("fill", "#6a9fbe").attr("stroke", "#4a7f9e").attr("stroke-width", 0.5);
    });

    // Right side: clean
    const rx = w / 2 + 20, rBarStart = w / 2 + 90;
    svg.append("text").attr("x", w * 3 / 4).attr("y", 20)
      .attr("text-anchor", "middle").attr("font-size", 11).attr("font-weight", 700)
      .attr("fill", T.fg).attr("font-family", T.sans).text("With space");

    data.forEach((d, i) => {
      const y = 42 + i * (barH + gap);
      const barW = (d.value / maxVal) * 140;
      svg.append("text").attr("x", rBarStart - 4).attr("y", y + barH / 2 + 1)
        .attr("text-anchor", "end").attr("font-size", 9).attr("fill", T.fg)
