function MinimalistSlide({ index, data, loading }: { index: number } & SectionProps) {
  if (index === 0) return (
    <SplitRow
      text={
        <div>
          <SectionTitle name="Edward Tufte" subtitle="The Data-Ink Ratio, 1983" />
          <p style={{ fontSize: 13, color: T.muted, lineHeight: 1.7, marginBottom: 0 }}>
            Tufte's first principle: maximize the data-ink ratio. Every drop of ink on a chart
            should represent data. Gridlines, borders, fills, 3D effects, redundant labels —
            he called it "chartjunk." Remove it, and what remains communicates faster. His
            redesign of the box plot is the canonical example: same information, a fraction
            of the ink.
          </p>
          <WikiLink href="https://en.wikipedia.org/wiki/Chartjunk" label="Chartjunk" />
          <DivePrompt prompt="Create a box plot showing distribution across categories. Then strip it down: remove the box fill, replace whisker caps with dots, use a single line for the IQR. Keep only the median line and the data range. Compare both versions side by side." />
          <KeyLesson text="Every pixel that isn't data is noise. The data-ink ratio is the share of ink devoted to data — maximize it, and the chart speaks for itself." />
        </div>
      }
      chart={
        <ChartFrame bg={T.bg} footnote="Traditional box plot vs Tufte's redesign. Same data, fraction of the ink.">
          <TufteBoxPlot />
        </ChartFrame>
      }
    />
  );

  if (index === 1) return (
    <SplitRow
      text={
        <div>
          <SectionTitle name="Sparklines" subtitle="Intense, Simple, Word-Sized Graphics, 2006" />
          <p style={{ fontSize: 13, color: T.muted, lineHeight: 1.7, marginBottom: 0 }}>
            Tufte wanted data where the words are — inline, word-sized, no axes, no labels.
            A sparkline is a "data word": a tiny time series that shows shape and trend in the
            space of a sentence. The reader doesn't stop to decode; they see "up", "volatile",
            "crashing" at a glance. The context is the surrounding text; the sparkline adds only
            the shape.
          </p>
          <WikiLink href="https://en.wikipedia.org/wiki/Sparkline" label="Sparklines" />
          <DivePrompt prompt="Create a data table where each row has a region name, a sparkline showing 12-month trend, and a current value. No axes on the sparklines — just the line. Add a red/green dot at the end to show direction. The sparkline should be word-sized, fitting inline with the text." />
          <KeyLesson text="The best chart is the one the reader doesn't notice. Sparklines live where the data lives — inline, contextual, invisible as infrastructure." />
        </div>
      }
      chart={
        <ChartFrame bg={T.bg} footnote="Word-sized data graphics. Each sparkline shows a 12-point trend; the dot marks the final value.">
          <SparklineTable data={data} loading={loading} />
        </ChartFrame>
      }
    />
  );

  if (index === 2) return (
    <SplitRow
      text={
        <div>
          <SectionTitle name="Small Multiples" subtitle="The Same Chart, Repeated" />
          <p style={{ fontSize: 13, color: T.muted, lineHeight: 1.7, marginBottom: 0 }}>
            Tufte's small multiples use the same chart structure repeated across categories.
            The reader learns the encoding once, then compares effortlessly. The eye does the
            work — no interaction needed, no animation, no tooltips. Just repetition with
            variation. It's the most underused technique in modern dashboards, and it's also
            the most effective for comparison.
          </p>
          <WikiLink href="https://en.wikipedia.org/wiki/Small_multiple" label="Small multiples" />
          <DivePrompt prompt="Create small multiples: the same bar chart repeated for each region. Same scale, same axis, same encoding. Arrange them in a 2×3 or 3×2 grid. The reader compares by scanning, not by hovering." />
          <KeyLesson text="Repetition is a feature, not a bug. When the encoding is identical, the eye does the comparison instantly — no interaction needed." />
        </div>
      }
      chart={
        <ChartFrame bg={T.bg} footnote="Small multiples: same chart, same scale, six regions. The eye compares without being told to.">
          <SmallMultiples data={data} loading={loading} />
        </ChartFrame>
      }
    />
  );

  return (
    <SplitRow
      text={
        <div>
          <SectionTitle name="Hans Rosling" subtitle="The Moving Bubble, 2006" />
          <p style={{ fontSize: 13, color: T.muted, lineHeight: 1.7, marginBottom: 0 }}>
            Rosling's genius was adding time to Tufte's clarity. His Gapminder bubble charts
            encoded four dimensions: x for income, y for life expectancy, size for population,
            color for continent. Then he pressed play, and the bubbles moved. Statistics became
            drama. You watched countries rise, fall, diverge. The animation didn't add complexity —
            it added narrative. The chart became a story.
          </p>
          <WikiLink href="https://en.wikipedia.org/wiki/Gapminder_Foundation" label="Gapminder Foundation" />
          <DivePrompt prompt="Create an animated bubble chart with x = GDP, y = life expectancy, size = population, color = region. Add a play/pause button and a year label. Animate through decades. Use trailing opacity to show trajectory. The motion tells the story." />
          <KeyLesson text="Animation isn't decoration — it's narrative. When a bubble moves, the reader watches a story unfold. Time is the dimension that turns statistics into drama." />
        </div>
      }
      chart={
        <ChartFrame bg={T.bg} footnote="Gapminder-style bubble chart. Press play to watch regions diverge over decades. Data is illustrative.">
          <RoslingBubbles />
        </ChartFrame>
      }
    />
  );
}

