// Box plot data: five-number summaries for 5 categories
const BOX_DATA = [
  { label: "SE Asia", min: 18, q1: 35, median: 53, q3: 68, max: 95 },
  { label: "W. Pacific", min: 10, q1: 25, median: 40, q3: 55, max: 78 },
  { label: "E. Med.", min: 12, q1: 28, median: 38, q3: 52, max: 72 },
  { label: "Africa", min: 8, q1: 18, median: 28, q3: 42, max: 60 },
  { label: "Europe", min: 3, q1: 8, median: 14, q3: 20, max: 32 },
];

function TufteBoxPlot() {
  const svgRef = useRef<SVGSVGElement>(null);

  useEffect(() => {
    if (!svgRef.current) return;
    const svg = d3.select(svgRef.current);
    svg.selectAll("*").remove();

    const w = 520, h = 260;
    svg.attr("viewBox", `0 0 ${w} ${h}`);

    const xScale = d3.scaleLinear().domain([0, 100]).range([90, 230]);
    const xScaleR = d3.scaleLinear().domain([0, 100]).range([w / 2 + 90, w / 2 + 230]);
    const rowH = 36;
    const startY = 50;

    // Titles
    svg.append("text").attr("x", 160).attr("y", 22)
      .attr("text-anchor", "middle").attr("font-size", 10).attr("font-weight", 700)
      .attr("fill", T.fg).attr("font-family", T.sans).text("Traditional");

    svg.append("text").attr("x", w / 2 + 160).attr("y", 22)
      .attr("text-anchor", "middle").attr("font-size", 10).attr("font-weight", 700)
      .attr("fill", T.fg).attr("font-family", T.sans).text("Tufte");

    // Divider
    svg.append("line").attr("x1", w / 2).attr("y1", 10).attr("x2", w / 2).attr("y2", h - 10)
      .attr("stroke", T.rule).attr("stroke-width", 1).attr("stroke-dasharray", "3,3");

    BOX_DATA.forEach((d, i) => {
      const y = startY + i * rowH;

      // ── Traditional (left) ──
      // Label
      svg.append("text").attr("x", 82).attr("y", y + 2)
        .attr("text-anchor", "end").attr("font-size", 9).attr("fill", T.fg)
        .attr("font-family", T.sans).text(d.label);

      // Whisker line
      svg.append("line")
        .attr("x1", xScale(d.min)).attr("y1", y).attr("x2", xScale(d.max)).attr("y2", y)
        .attr("stroke", "#666").attr("stroke-width", 1);

      // Whisker caps
      svg.append("line").attr("x1", xScale(d.min)).attr("y1", y - 6).attr("x2", xScale(d.min)).attr("y2", y + 6)
        .attr("stroke", "#666").attr("stroke-width", 1);
      svg.append("line").attr("x1", xScale(d.max)).attr("y1", y - 6).attr("x2", xScale(d.max)).attr("y2", y + 6)
        .attr("stroke", "#666").attr("stroke-width", 1);

      // Box
      svg.append("rect")
        .attr("x", xScale(d.q1)).attr("y", y - 8).attr("width", xScale(d.q3) - xScale(d.q1)).attr("height", 16)
        .attr("fill", "#b8ccd8").attr("stroke", "#666").attr("stroke-width", 1);

      // Median line
      svg.append("line")
        .attr("x1", xScale(d.median)).attr("y1", y - 8).attr("x2", xScale(d.median)).attr("y2", y + 8)
        .attr("stroke", "#333").attr("stroke-width", 2);

      // ── Tufte (right) ──
      // Label
      svg.append("text").attr("x", w / 2 + 82).attr("y", y + 2)
        .attr("text-anchor", "end").attr("font-size", 9).attr("fill", T.fg)
        .attr("font-family", T.sans).text(d.label);

      // Thin whisker line (min to q1, q3 to max)
      svg.append("line")
        .attr("x1", xScaleR(d.min)).attr("y1", y).attr("x2", xScaleR(d.q1)).attr("y2", y)
        .attr("stroke", T.fg).attr("stroke-width", 0.8);
      svg.append("line")
        .attr("x1", xScaleR(d.q3)).attr("y1", y).attr("x2", xScaleR(d.max)).attr("y2", y)
        .attr("stroke", T.fg).attr("stroke-width", 0.8);

      // Thick IQR line (q1 to q3)
      svg.append("line")
        .attr("x1", xScaleR(d.q1)).attr("y1", y).attr("x2", xScaleR(d.q3)).attr("y2", y)
        .attr("stroke", T.fg).attr("stroke-width", 4);

      // Median dot (white gap)
      svg.append("circle")
        .attr("cx", xScaleR(d.median)).attr("cy", y).attr("r", 3)
        .attr("fill", "#fff").attr("stroke", T.fg).attr("stroke-width", 1.5);
    });

    // Axis labels
    [0, 25, 50, 75, 100].forEach(v => {
      svg.append("text").attr("x", xScale(v)).attr("y", h - 12)
        .attr("text-anchor", "middle").attr("font-size", 8).attr("fill", T.muted)
        .attr("font-family", T.sans).text(v);
      svg.append("text").attr("x", xScaleR(v)).attr("y", h - 12)
        .attr("text-anchor", "middle").attr("font-size", 8).attr("fill", T.muted)
        .attr("font-family", T.sans).text(v);
    });
  }, []);

  return <svg ref={svgRef} style={{ width: "100%", height: "auto", aspectRatio: "520/260" }} />;
}

function SparklineTable({ data, loading }: { data: SectionProps["data"]; loading: boolean }) {
  if (loading) return <div style={{ background: "#f3f4f6", borderRadius: 4, height: 160 }} />;

  // Generate fake 12-point trends per region
  const trends: Record<string, number[]> = {};
  data.forEach(r => {
    const base = r.avg_pm25;
    trends[r.region] = Array.from({ length: 12 }, (_, i) =>
      base + (Math.sin(i * 0.8) * base * 0.15) + (Math.random() - 0.5) * base * 0.1
    );
  });

  return (
    <div style={{ display: "flex", flexDirection: "column", gap: 0 }}>
      {/* Header */}
      <div style={{ display: "flex", alignItems: "center", padding: "0 0 8px", borderBottom: `1px solid ${T.rule}` }}>
        <span style={{ width: 100, fontSize: 9, fontWeight: 700, color: T.muted, textTransform: "uppercase", letterSpacing: "0.06em" }}>Region</span>
        <span style={{ flex: 1, fontSize: 9, fontWeight: 700, color: T.muted, textTransform: "uppercase", letterSpacing: "0.06em" }}>12-month trend</span>
        <span style={{ width: 60, fontSize: 9, fontWeight: 700, color: T.muted, textTransform: "uppercase", letterSpacing: "0.06em", textAlign: "right" }}>Current</span>
      </div>
      {data.map(r => {
        const pts = trends[r.region];
        const min = Math.min(...pts), max = Math.max(...pts);
        const range = max - min || 1;
        const sparkW = 120, sparkH = 24;
        const pathD = pts.map((v, i) =>
          `${i === 0 ? "M" : "L"} ${(i / 11) * sparkW} ${sparkH - ((v - min) / range) * sparkH}`
        ).join(" ");
        const lastVal = pts[pts.length - 1];
        const prevVal = pts[pts.length - 2];
        const up = lastVal >= prevVal;

        return (
          <div key={r.region} style={{ display: "flex", alignItems: "center", padding: "8px 0", borderBottom: `1px solid ${T.rule}` }}>
            <span style={{ width: 100, fontSize: 11, fontWeight: 600, color: T.fg }}>{r.region}</span>
            <div style={{ flex: 1 }}>
              <svg width={sparkW + 8} height={sparkH + 4} style={{ display: "block" }}>
                <path d={pathD} fill="none" stroke={T.fg} strokeWidth="1.2" transform="translate(0,2)" />
                <circle cx={(11 / 11) * sparkW} cy={sparkH - ((lastVal - min) / range) * sparkH + 2} r="3"
                  fill={up ? "#c45b6a" : "#16AA98"} />
              </svg>
            </div>
            <span style={{ width: 60, fontSize: 14, fontWeight: 700, color: T.fg, textAlign: "right" }}>
              {r.avg_pm25}
            </span>
          </div>
        );
      })}
    </div>
  );
}

function SmallMultiples({ data, loading }: { data: SectionProps["data"]; loading: boolean }) {
  if (loading) return <div style={{ background: "#f3f4f6", borderRadius: 4, height: 200 }} />;

  // Fake monthly data per region
  const months = ["J", "F", "M", "A", "M", "J", "J", "A", "S", "O", "N", "D"];
  const monthlyData: Record<string, number[]> = {};
  data.forEach(r => {
    const base = r.avg_pm25;
    monthlyData[r.region] = months.map((_, i) =>
      Math.max(1, base + Math.sin((i - 3) * 0.5) * base * 0.3 + (Math.random() - 0.5) * base * 0.15)
    );
  });

  const globalMax = Math.max(...Object.values(monthlyData).flat());

  return (
    <div style={{ display: "grid", gridTemplateColumns: "repeat(3, 1fr)", gap: 12 }}>
      {data.map(r => {
        const vals = monthlyData[r.region];
        const barW = 6, gap = 2;

        return (
          <div key={r.region} style={{ padding: "8px 0" }}>
            <p style={{ fontSize: 9, fontWeight: 700, color: T.fg, marginBottom: 6, textTransform: "uppercase", letterSpacing: "0.06em" }}>
              {r.region}
            </p>
            <svg width={months.length * (barW + gap)} height={50} style={{ display: "block" }}>
              {vals.map((v, i) => {
                const barH = (v / globalMax) * 40;
                return (
                  <rect key={i} x={i * (barW + gap)} y={40 - barH} width={barW} height={barH}
                    fill={T.fg} opacity={0.7} />
                );
              })}
            </svg>
            <div style={{ display: "flex", justifyContent: "space-between", marginTop: 2 }}>
              <span style={{ fontSize: 7, color: T.muted }}>Jan</span>
              <span style={{ fontSize: 7, color: T.muted }}>Dec</span>
            </div>
          </div>
        );
      })}
    </div>
  );
}

// ── Rosling Gapminder-style animated bubble chart ─────────────────

const BUBBLE_REGIONS = [
  { name: "East Asia", color: "#6FC2FF", pop: 1.5 },
  { name: "Europe", color: "#16AA98", pop: 0.7 },
  { name: "Sub-Saharan Africa", color: "#FFDE02", pop: 1.1 },
  { name: "South Asia", color: "#FF7169", pop: 1.8 },
  { name: "Americas", color: "#383838", pop: 0.9 },
];

const BUBBLE_YEARS = Array.from({ length: 7 }, (_, i) => 1960 + i * 10);

// Generate smooth trajectories
function generateTrajectories() {
  const data: Record<string, { year: number; gdp: number; life: number }[]> = {};
  BUBBLE_REGIONS.forEach(r => {
    const base = { gdp: 500 + Math.random() * 2000, life: 40 + Math.random() * 15 };
    const growth = 0.8 + Math.random() * 0.6;
    data[r.name] = BUBBLE_YEARS.map((year, i) => ({
      year,
      gdp: Math.round(base.gdp * Math.pow(1 + growth * 0.1, i * 2) + (Math.random() - 0.3) * 500),
      life: Math.min(85, base.life + i * (3 + Math.random() * 2)),
    }));
  });
  return data;
}

const BUBBLE_TRAJECTORIES = generateTrajectories();

function RoslingBubbles() {
  const svgRef = useRef<SVGSVGElement>(null);
  const [yearIdx, setYearIdx] = useState(0);
  const [playing, setPlaying] = useState(false);
  const intervalRef = useRef<ReturnType<typeof setInterval> | null>(null);

  useEffect(() => {
    if (playing) {
      intervalRef.current = setInterval(() => {
        setYearIdx(prev => {
          if (prev >= BUBBLE_YEARS.length - 1) { setPlaying(false); return prev; }
          return prev + 1;
        });
      }, 1200);
    }
    return () => { if (intervalRef.current) clearInterval(intervalRef.current); };
  }, [playing]);

  useEffect(() => {
    if (!svgRef.current) return;
    const svg = d3.select(svgRef.current);
    svg.selectAll("*").remove();

    const w = 460, h = 280;
    const m = { top: 20, right: 20, bottom: 40, left: 50 };
    svg.attr("viewBox", `0 0 ${w} ${h}`);

    const xScale = d3.scaleLog().domain([400, 60000]).range([m.left, w - m.right]);
    const yScale = d3.scaleLinear().domain([30, 90]).range([h - m.bottom, m.top]);

    // Grid lines
    [1000, 5000, 20000, 50000].forEach(v => {
      svg.append("line")
        .attr("x1", xScale(v)).attr("y1", m.top).attr("x2", xScale(v)).attr("y2", h - m.bottom)
        .attr("stroke", T.rule).attr("stroke-width", 0.5);
      svg.append("text").attr("x", xScale(v)).attr("y", h - m.bottom + 14)
        .attr("text-anchor", "middle").attr("font-size", 8).attr("fill", T.muted)
        .attr("font-family", T.sans).text(v >= 1000 ? `$${v / 1000}k` : `$${v}`);
    });

    [40, 50, 60, 70, 80].forEach(v => {
      svg.append("line")
        .attr("x1", m.left).attr("y1", yScale(v)).attr("x2", w - m.right).attr("y2", yScale(v))
        .attr("stroke", T.rule).attr("stroke-width", 0.5);
      svg.append("text").attr("x", m.left - 6).attr("y", yScale(v) + 3)
        .attr("text-anchor", "end").attr("font-size", 8).attr("fill", T.muted)
        .attr("font-family", T.sans).text(v);
    });

    // Axis labels
    svg.append("text").attr("x", w / 2).attr("y", h - 6)
      .attr("text-anchor", "middle").attr("font-size", 9).attr("fill", T.muted)
      .attr("font-family", T.sans).text("GDP per capita (log scale)");
    svg.append("text").attr("x", 12).attr("y", h / 2)
      .attr("text-anchor", "middle").attr("font-size", 9).attr("fill", T.muted)
      .attr("font-family", T.sans).attr("transform", `rotate(-90, 12, ${h / 2})`)
      .text("Life expectancy");

    // Year watermark
    svg.append("text").attr("x", w / 2).attr("y", h / 2 + 10)
      .attr("text-anchor", "middle").attr("font-size", 64).attr("font-weight", 900)
      .attr("fill", T.rule).attr("opacity", 0.4)
      .attr("font-family", T.sans).text(BUBBLE_YEARS[yearIdx]);

    // Trail (faded previous positions)
    BUBBLE_REGIONS.forEach(r => {
      const pts = BUBBLE_TRAJECTORIES[r.name];
      for (let i = 0; i < yearIdx; i++) {
        const p = pts[i];
        const gdpClamped = Math.max(400, Math.min(60000, p.gdp));
        svg.append("circle")
          .attr("cx", xScale(gdpClamped)).attr("cy", yScale(p.life))
          .attr("r", r.pop * 6).attr("fill", r.color).attr("opacity", 0.15);
      }
    });

    // Current bubbles
    BUBBLE_REGIONS.forEach(r => {
      const p = BUBBLE_TRAJECTORIES[r.name][yearIdx];
      const gdpClamped = Math.max(400, Math.min(60000, p.gdp));
      svg.append("circle")
        .attr("cx", xScale(gdpClamped)).attr("cy", yScale(p.life))
        .attr("r", r.pop * 12).attr("fill", r.color).attr("opacity", 0.75)
        .attr("stroke", r.color).attr("stroke-width", 1.5);
    });
  }, [yearIdx]);

  const handlePlayPause = () => {
    if (yearIdx >= BUBBLE_YEARS.length - 1) { setYearIdx(0); setPlaying(true); }
    else setPlaying(!playing);
  };

  return (
    <div>
      <svg ref={svgRef} style={{ width: "100%", height: "auto", aspectRatio: "460/280" }} />
      <div style={{ display: "flex", alignItems: "center", gap: 12, marginTop: 8 }}>
        <button onClick={handlePlayPause} style={{
          background: T.fg, color: "#fff", border: "none", borderRadius: 3,
          padding: "4px 12px", fontSize: 11, fontWeight: 600, cursor: "pointer",
          fontFamily: T.sans,
        }}>
          {playing ? "Pause" : yearIdx >= BUBBLE_YEARS.length - 1 ? "Replay" : "Play"}
        </button>
        <div style={{ display: "flex", gap: 4 }}>
          {BUBBLE_YEARS.map((y, i) => (
            <button key={y} onClick={() => { setPlaying(false); setYearIdx(i); }} style={{
              background: "none", border: "none", cursor: "pointer", padding: "2px 4px",
              fontSize: 10, fontWeight: i === yearIdx ? 700 : 400,
              color: i === yearIdx ? T.fg : T.muted, fontFamily: T.sans,
              textDecoration: i === yearIdx ? "underline" : "none",
            }}>
              {y}
            </button>
          ))}
        </div>
      </div>
      <LegendRow items={BUBBLE_REGIONS.map(r => ({ color: r.color, label: r.name }))} />
    </div>
  );
}

