function InteractiveSlide({ index, data, loading }: { index: number } & SectionProps) {
  if (index === 0) return (
    <SplitRow
      text={
        <div>
          <SectionTitle name="The Highlight Principle" subtitle="One Color, Everything Else Grey" />
          <p style={{ fontSize: 13, color: T.muted, lineHeight: 1.7, marginBottom: 0 }}>
            The NYT graphics desk works under a brutal constraint: 45 seconds of reader
            attention, no statistical background, on a phone. Their solution is radical
            simplicity: one highlight color, everything else grey. Click a bar and it lights
            up — the rest recedes. This is figure-ground as interface. The reader
            doesn't analyze; they point and discover.
          </p>
          <WikiLink href="https://en.wikipedia.org/wiki/The_New_York_Times_visual_journalism" label="NYT visual journalism" />
          <DivePrompt prompt="Create a bar chart where all bars start grey. On click, the selected bar turns to the accent color and all others fade. Add a label above the highlighted bar. The interaction IS the analysis — clicking is thinking." />
          <KeyLesson text="Interaction isn't decoration — it's analysis. When the reader clicks, they're asking a question. The chart should answer it instantly." />
        </div>
      }
      chart={
        <ChartFrame bg={T.bg} footnote="Hover a bar to highlight. One color for signal, grey for context. WHO PM2.5 data.">
          <HighlightBars data={data} loading={loading} />
        </ChartFrame>
      }
    />
  );

  if (index === 1) return (
    <SplitRow
      text={
        <div>
          <SectionTitle name="Annotation as Narrative" subtitle="The Chart That Reads Itself" />
          <p style={{ fontSize: 13, color: T.muted, lineHeight: 1.7, marginBottom: 0 }}>
            Amanda Cox at the NYT pioneered charts that tell their own story. Instead of
            requiring the reader to discover the insight, the annotation points to it. A line
            with a callout saying "This is when everything changed" does in one sentence what
            a legend, axis label, and tooltip cannot. The annotation is the editorial voice —
            it says "look here, this matters."
          </p>
          <WikiLink href="https://en.wikipedia.org/wiki/Amanda_Cox" label="Amanda Cox" />
          <DivePrompt prompt="Create a line chart showing a trend. Add a text annotation with an arrow pointing to the key moment — e.g., 'Policy change' or 'Peak reached.' The annotation is the editorial voice: it tells the reader what to see and why it matters." />
          <KeyLesson text="Don't make the reader find the story. Point to it. An annotation says 'this matters' in a way that axes and legends never can." />
        </div>
      }
      chart={
        <ChartFrame bg={T.bg} footnote="Annotated line chart. The text IS the insight — the reader doesn't need to discover it.">
          <AnnotatedChart />
        </ChartFrame>
      }
    />
  );

  if (index === 2) return (
    <SplitRow
      text={
        <div>
          <SectionTitle name="The Stepper" subtitle="Scrollytelling in a Box" />
          <p style={{ fontSize: 13, color: T.muted, lineHeight: 1.7, marginBottom: 0 }}>
            Before scrollytelling took over the web, the NYT used steppers: a chart with
            numbered steps that changed what was shown. Step 1 shows all bars. Step 2
            highlights the worst. Step 3 adds context. Each step is a sentence, and each
            sentence changes the chart. The reader controls the pace, but the designer
            controls the narrative. It's a presentation that respects the reader's autonomy.
          </p>
          <WikiLink href="https://en.wikipedia.org/wiki/Scrollytelling" label="Scrollytelling" />
          <DivePrompt prompt="Create a stepper chart with 3-4 steps. Each step changes what's highlighted or filtered. Use numbered buttons. Each step should have a one-sentence explanation. The reader advances at their own pace but follows your narrative." />
          <KeyLesson text="Control the narrative, respect the reader's pace. Each step reveals one insight — no more, no less. The reader advances when they're ready." />
        </div>
      }
      chart={
        <ChartFrame bg={T.bg} footnote="Step through the data: each step reveals one layer of insight. Click the numbered steps.">
          <StepperChart data={data} loading={loading} />
        </ChartFrame>
      }
    />
  );

  return (
    <SplitRow
      text={
        <div>
          <SectionTitle name="Mike Bostock & D3" subtitle="Data-Driven Documents, 2011" />
          <p style={{ fontSize: 13, color: T.muted, lineHeight: 1.7, marginBottom: 0 }}>
            D3 didn't invent interactive visualization. It made it possible for newsrooms.
            By binding data to DOM elements, Bostock turned every SVG shape into a data point
            that could respond to hover, click, drag, and scroll. The abstraction was
            radical: not "draw a chart," but "bind data to shapes and let the browser render."
            This is why D3 powers every major newsroom's graphics and why it remains the
            foundation of modern data visualization on the web.
          </p>
          <WikiLink href="https://en.wikipedia.org/wiki/D3.js" label="D3.js" />
          <DivePrompt prompt="Create a chart where hovering a data point reveals connected details: a tooltip, a highlight line, and related points that light up. Use transitions for smooth state changes. The interaction should feel inevitable — the reader hovers because the shape invites it." />
          <KeyLesson text="D3's insight: a chart is not a picture. It's a set of data bindings. Every shape knows what it represents, and can respond when asked." />
        </div>
      }
      chart={
        <ChartFrame bg={T.bg} footnote="Hover to explore. Every element responds because every element is bound to data. WHO air quality.">
          <D3HoverChart data={data} loading={loading} />
        </ChartFrame>
      }
    />
  );
}

/* ── Tab 4 chart components ─────────────────────────────────────── */

function HighlightBars({ data, loading }: { data: SectionProps["data"]; loading: boolean }) {
  const [hovered, setHovered] = useState<string | null>(null);
  const sorted = [...data].sort((a, b) => b.avg_pm25 - a.avg_pm25);

  if (loading) return <div style={{ background: "#f3f4f6", borderRadius: 4, height: 200 }} />;

  const maxPm = sorted[0]?.avg_pm25 || 1;

  return (
    <div>
      <div style={{ display: "flex", flexDirection: "column", gap: 8 }}>
        {sorted.map(r => {
          const isHovered = hovered === r.region;
          const isOther = hovered !== null && !isHovered;
          const barW = (r.avg_pm25 / maxPm) * 100;

          return (
            <div key={r.region}
              onMouseEnter={() => setHovered(r.region)}
              onMouseLeave={() => setHovered(null)}
              style={{ display: "flex", alignItems: "center", gap: 8, cursor: "pointer" }}
            >
              <span style={{
                width: 90, fontSize: 10, textAlign: "right", flexShrink: 0,
                color: isHovered ? T.fg : isOther ? T.muted : T.fg,
                fontWeight: isHovered ? 700 : 400,
                transition: "all 0.2s ease",
              }}>
                {r.region}
              </span>
              <div style={{ flex: 1, position: "relative" }}>
                <div style={{
                  width: `${barW}%`, height: 24,
                  background: isHovered ? T.accent : "#d9d9d9",
                  borderRadius: "0 2px 2px 0",
                  transition: "all 0.2s ease",
                }} />
              </div>
              <span style={{
                width: 36, fontSize: isHovered ? 13 : 10, fontWeight: 700,
                color: isHovered ? T.accent : T.fg, textAlign: "right",
                transition: "all 0.2s ease",
              }}>
                {r.avg_pm25}
              </span>
            </div>
          );
        })}
      </div>
      <div style={{ minHeight: 24, marginTop: 8 }}>
        {hovered ? (
          <p style={{ fontSize: 11, color: T.muted, margin: 0 }}>
            <strong style={{ color: T.fg }}>{hovered}</strong>: {sorted.find(s => s.region === hovered)?.avg_pm25} µg/m³ average PM2.5 across {sorted.find(s => s.region === hovered)?.cities} cities
          </p>
        ) : (
          <p style={{ fontSize: 10, color: T.muted, fontStyle: "italic", margin: 0 }}>Hover over a bar to highlight</p>
        )}
      </div>
    </div>
  );
}

function AnnotatedChart() {
  const svgRef = useRef<SVGSVGElement>(null);

  useEffect(() => {
    if (!svgRef.current) return;
    const svg = d3.select(svgRef.current);
    svg.selectAll("*").remove();

    const w = 480, h = 260;
    const m = { top: 40, right: 40, bottom: 30, left: 40 };
    svg.attr("viewBox", `0 0 ${w} ${h}`);

    // Fake trend data: PM2.5 over years
    const years = Array.from({ length: 15 }, (_, i) => 2008 + i);
    const values = [42, 45, 48, 52, 55, 53, 50, 44, 38, 35, 34, 32, 30, 28, 27];
    const peakIdx = 4; // 2012
    const policyIdx = 7; // 2015

    const xScale = d3.scaleLinear().domain([2008, 2022]).range([m.left, w - m.right]);
    const yScale = d3.scaleLinear().domain([20, 60]).range([h - m.bottom, m.top]);

    // Subtle grid
    [20, 30, 40, 50, 60].forEach(v => {
      svg.append("line")
        .attr("x1", m.left).attr("y1", yScale(v)).attr("x2", w - m.right).attr("y2", yScale(v))
        .attr("stroke", T.rule).attr("stroke-width", 0.5);
      svg.append("text").attr("x", m.left - 6).attr("y", yScale(v) + 3)
        .attr("text-anchor", "end").attr("font-size", 8).attr("fill", T.muted)
        .attr("font-family", T.sans).text(v);
    });

    // X axis labels
    [2008, 2012, 2016, 2020].forEach(y => {
      svg.append("text").attr("x", xScale(y)).attr("y", h - 10)
        .attr("text-anchor", "middle").attr("font-size", 8).attr("fill", T.muted)
        .attr("font-family", T.sans).text(y);
    });

    // Line
    const line = d3.line<number>()
      .x((_, i) => xScale(years[i]))
      .y(d => yScale(d))
      .curve(d3.curveMonotoneX);

    svg.append("path").datum(values)
      .attr("d", line).attr("fill", "none").attr("stroke", T.fg).attr("stroke-width", 2);

    // Peak annotation — pointing up-right from the peak
    const peakX = xScale(years[peakIdx]), peakY = yScale(values[peakIdx]);
    svg.append("circle").attr("cx", peakX).attr("cy", peakY).attr("r", 4)
      .attr("fill", "#FF7169").attr("stroke", "#fff").attr("stroke-width", 1.5);

    // Leader line goes up-left to avoid right edge
    svg.append("line").attr("x1", peakX).attr("y1", peakY - 8).attr("x2", peakX + 20).attr("y2", peakY - 28)
      .attr("stroke", "#FF7169").attr("stroke-width", 1);
    svg.append("text").attr("x", peakX + 24).attr("y", peakY - 32)
      .attr("font-size", 10).attr("font-weight", 700).attr("fill", "#FF7169")
      .attr("font-family", T.sans).text("Peak: 55 µg/m³");
    svg.append("text").attr("x", peakX + 24).attr("y", peakY - 20)
      .attr("font-size", 9).attr("fill", T.muted)
      .attr("font-family", T.sans).text("Before policy change");

    // Policy annotation — pointing down-left
    const polX = xScale(years[policyIdx]), polY = yScale(values[policyIdx]);
    svg.append("circle").attr("cx", polX).attr("cy", polY).attr("r", 4)
      .attr("fill", "#16AA98").attr("stroke", "#fff").attr("stroke-width", 1.5);

    svg.append("line").attr("x1", polX).attr("y1", polY + 8).attr("x2", polX - 20).attr("y2", polY + 30)
      .attr("stroke", "#16AA98").attr("stroke-width", 1);
    svg.append("text").attr("x", polX - 24).attr("y", polY + 34)
      .attr("text-anchor", "end").attr("font-size", 10).attr("font-weight", 700).attr("fill", "#16AA98")
      .attr("font-family", T.sans).text("Clean Air Act");
    svg.append("text").attr("x", polX - 24).attr("y", polY + 46)
      .attr("text-anchor", "end").attr("font-size", 9).attr("fill", T.muted)
      .attr("font-family", T.sans).text("Decline accelerates");

    // End value
    const lastX = xScale(years[years.length - 1]), lastY = yScale(values[values.length - 1]);
    svg.append("circle").attr("cx", lastX).attr("cy", lastY).attr("r", 3)
      .attr("fill", T.fg);
    svg.append("text").attr("x", lastX - 6).attr("y", lastY + 16)
      .attr("text-anchor", "end").attr("font-size", 11).attr("font-weight", 700).attr("fill", T.fg)
      .attr("font-family", T.sans).text("27");
  }, []);

  return <svg ref={svgRef} style={{ width: "100%", height: "auto", aspectRatio: "480/260" }} />;
}

function StepperChart({ data, loading }: { data: SectionProps["data"]; loading: boolean }) {
  const [step, setStep] = useState(0);
  const [hoveredBar, setHoveredBar] = useState<string | null>(null);
  const sorted = [...data].sort((a, b) => b.avg_pm25 - a.avg_pm25);

  if (loading) return <div style={{ background: "#f3f4f6", borderRadius: 4, height: 280 }} />;

  const steps = [
    { label: "All regions", description: "Average PM2.5 concentration by WHO region, ranked highest to lowest." },
    { label: "The worst", description: "Southeast Asia leads with more than 5× the pollution of the cleanest region." },
    { label: "WHO guideline", description: "The WHO recommends less than 10 µg/m³. Only the Americas passes." },
    { label: "The gap", description: "43 µg/m³ separates the most polluted region from the cleanest." },
  ];

  const whoGuideline = 10;
  const maxPm = sorted[0]?.avg_pm25 || 1;

  return (
    <div>
      {/* Step buttons */}
      <div style={{ display: "flex", gap: 1, marginBottom: 20, background: T.rule }}>
        {steps.map((s, i) => (
          <button key={i} onClick={() => setStep(i)} style={{
            flex: 1, padding: "10px 8px", border: "none", cursor: "pointer",
            background: i === step ? T.fg : T.bg,
            color: i === step ? "#fff" : T.muted,
            fontSize: 10, fontWeight: i === step ? 700 : 400,
            fontFamily: T.sans,
          }}>
            <span style={{ display: "block", fontSize: 16, fontWeight: 800, marginBottom: 3 }}>{i + 1}</span>
            {s.label}
          </button>
        ))}
      </div>

      {/* Step description */}
      <p style={{ fontSize: 13, fontWeight: 600, color: T.fg, marginBottom: 20, lineHeight: 1.5 }}>
        {steps[step].description}
      </p>

      {/* Chart */}
      <div style={{ display: "flex", flexDirection: "column", gap: 10 }}>
        {sorted.map((r, i) => {
          const barW = (r.avg_pm25 / maxPm) * 100;
          const isBarHovered = hoveredBar === r.region;

          let fill = T.fg;
          let opacity = 0.7;
          if (step === 1) {
            fill = i === 0 ? "#FF7169" : "#d9d9d9";
            opacity = 1;
          } else if (step === 2) {
            fill = r.avg_pm25 <= whoGuideline ? "#16AA98" : "#d9d9d9";
            opacity = 1;
          } else if (step === 3) {
            fill = (i === 0 || i === sorted.length - 1) ? T.accent : "#d9d9d9";
            opacity = 1;
          }

          // Hover overrides
          if (isBarHovered) { fill = T.accent; opacity = 1; }

          return (
            <div key={r.region}
              onMouseEnter={() => setHoveredBar(r.region)}
              onMouseLeave={() => setHoveredBar(null)}
              style={{ display: "flex", alignItems: "center", gap: 10, cursor: "default" }}
            >
              <span style={{
                width: 90, fontSize: 10, textAlign: "right", flexShrink: 0,
                color: isBarHovered ? T.fg : T.fg,
                fontWeight: isBarHovered ? 700 : 400,
              }}>
                {r.region}
              </span>
              <div style={{ flex: 1, position: "relative" }}>
                <div style={{
                  width: `${barW}%`, height: 26, background: fill, opacity,
                  borderRadius: "0 2px 2px 0", transition: "all 0.3s ease",
                }} />
                {step === 2 && (
                  <div style={{
                    position: "absolute", left: `${(whoGuideline / maxPm) * 100}%`, top: -3,
                    width: 1.5, height: 32, background: "#16AA98",
                  }} />
                )}
              </div>
              <span style={{
                width: 40, fontSize: 11, fontWeight: 700, color: T.fg, textAlign: "right",
              }}>
                {r.avg_pm25}
              </span>
            </div>
          );
        })}
      </div>

      {/* Hover details */}
      <div style={{ minHeight: 20, marginTop: 10 }}>
        {hoveredBar ? (
          <p style={{ fontSize: 11, color: T.muted, margin: 0 }}>
            <strong style={{ color: T.fg }}>{hoveredBar}</strong>: {sorted.find(s => s.region === hoveredBar)?.avg_pm25} µg/m³ across {sorted.find(s => s.region === hoveredBar)?.cities} cities in {sorted.find(s => s.region === hoveredBar)?.countries} countries
          </p>
        ) : step === 2 ? (
          <div style={{ display: "flex", alignItems: "center", gap: 4 }}>
            <div style={{ width: 12, height: 1.5, background: "#16AA98" }} />
            <span style={{ fontSize: 9, color: "#16AA98" }}>WHO guideline: 10 µg/m³</span>
          </div>
        ) : null}
      </div>

      {/* Next step button */}
      <div style={{ display: "flex", justifyContent: "flex-end", marginTop: 16 }}>
        {step < steps.length - 1 ? (
          <button onClick={() => setStep(step + 1)} style={{
            background: "none", border: `1px solid ${T.rule}`, borderRadius: 3,
            padding: "6px 16px", fontSize: 11, color: T.fg, cursor: "pointer",
            fontFamily: T.sans, fontWeight: 600,
            display: "flex", alignItems: "center", gap: 6,
          }}>
            Next: {steps[step + 1].label}
            <span style={{ fontSize: 14 }}>→</span>
          </button>
        ) : (
          <button onClick={() => setStep(0)} style={{
            background: "none", border: `1px solid ${T.rule}`, borderRadius: 3,
            padding: "6px 16px", fontSize: 11, color: T.muted, cursor: "pointer",
            fontFamily: T.sans, fontWeight: 400,
          }}>
            Restart from step 1
          </button>
        )}
      </div>
    </div>
  );
}

function D3HoverChart({ data, loading }: { data: SectionProps["data"]; loading: boolean }) {
  const svgRef = useRef<SVGSVGElement>(null);
  const [hovered, setHovered] = useState<string | null>(null);

  useEffect(() => {
    if (!svgRef.current || loading || data.length === 0) return;
    const svg = d3.select(svgRef.current);
    svg.selectAll("*").remove();

    const w = 460, h = 240;
    const m = { top: 10, right: 20, bottom: 30, left: 50 };
    svg.attr("viewBox", `0 0 ${w} ${h}`);

    const xScale = d3.scaleLinear().domain([0, d3.max(data, d => d.cities) || 100]).range([m.left, w - m.right]);
    const yScale = d3.scaleLinear().domain([0, d3.max(data, d => d.avg_pm25) || 60]).range([h - m.bottom, m.top]);
    const rScale = d3.scaleSqrt().domain([0, d3.max(data, d => d.countries) || 50]).range([6, 28]);

    // Subtle grid
    svg.append("line").attr("x1", m.left).attr("y1", h - m.bottom).attr("x2", w - m.right).attr("y2", h - m.bottom)
      .attr("stroke", T.rule).attr("stroke-width", 0.5);
    svg.append("line").attr("x1", m.left).attr("y1", m.top).attr("x2", m.left).attr("y2", h - m.bottom)
      .attr("stroke", T.rule).attr("stroke-width", 0.5);

    // Axis labels
    svg.append("text").attr("x", w / 2).attr("y", h - 6)
      .attr("text-anchor", "middle").attr("font-size", 9).attr("fill", T.muted)
      .attr("font-family", T.sans).text("Cities monitored");
    svg.append("text").attr("x", 12).attr("y", h / 2)
      .attr("text-anchor", "middle").attr("font-size", 9).attr("fill", T.muted)
      .attr("font-family", T.sans).attr("transform", `rotate(-90, 12, ${h / 2})`)
      .text("PM2.5 (µg/m³)");

    // Crosshair lines (hidden initially, shown on hover)
    if (hovered) {
      const d = data.find(r => r.region === hovered);
      if (d) {
        svg.append("line")
          .attr("x1", xScale(d.cities)).attr("y1", m.top).attr("x2", xScale(d.cities)).attr("y2", h - m.bottom)
          .attr("stroke", T.accent).attr("stroke-width", 0.8).attr("stroke-dasharray", "3,3");
        svg.append("line")
          .attr("x1", m.left).attr("y1", yScale(d.avg_pm25)).attr("x2", w - m.right).attr("y2", yScale(d.avg_pm25))
          .attr("stroke", T.accent).attr("stroke-width", 0.8).attr("stroke-dasharray", "3,3");
      }
    }

    // Bubbles
    data.forEach(d => {
      const isHovered = hovered === d.region;
      const isOther = hovered !== null && !isHovered;

      svg.append("circle")
        .attr("cx", xScale(d.cities)).attr("cy", yScale(d.avg_pm25))
        .attr("r", rScale(d.countries))
        .attr("fill", isOther ? "#d9d9d9" : T.accent)
        .attr("opacity", isOther ? 0.4 : 0.6)
        .attr("stroke", isHovered ? T.fg : "none")
        .attr("stroke-width", isHovered ? 2 : 0)
        .attr("cursor", "pointer")
        .on("mouseenter", () => setHovered(d.region))
        .on("mouseleave", () => setHovered(null));

      // Label
      if (!hovered || isHovered) {
        svg.append("text")
          .attr("x", xScale(d.cities)).attr("y", yScale(d.avg_pm25) - rScale(d.countries) - 4)
          .attr("text-anchor", "middle").attr("font-size", isHovered ? 11 : 9)
          .attr("font-weight", isHovered ? 700 : 400)
          .attr("fill", T.fg).attr("font-family", T.sans)
          .text(d.region)
          .style("pointer-events", "none");
      }
    });
  }, [data, loading, hovered]);

  if (loading) return <div style={{ background: "#f3f4f6", borderRadius: 4, height: 200 }} />;

  return (
    <div>
      <svg ref={svgRef} style={{ width: "100%", height: "auto", aspectRatio: "460/240" }} />
      {hovered && (() => {
        const d = data.find(r => r.region === hovered);
        return d ? (
          <p style={{ fontSize: 11, color: T.muted, marginTop: 4 }}>
            <strong style={{ color: T.fg }}>{d.region}</strong>: {d.avg_pm25} µg/m³ avg · {d.cities} cities · {d.countries} countries
          </p>
        ) : null;
      })()}
      <LegendRow items={[
        { color: T.accent, label: "Bubble size = countries reporting" },
      ]} />
    </div>
  );
}
